// CreateOrFail builds a character and inserts it into the database
// Relations objects are also inserted and placed in the .R field
// It calls `tb.Fatal(err)` on the test/benchmark if an error occurs
func (o *CharacterTemplate) CreateOrFail(ctx context.Context, tb testing.TB, exec bob.Executor) *models.Character {
	tb.Helper()
	m, err := o.Create(ctx, exec)
	if err != nil {
		tb.Fatal(err)
		return nil
	}
	return m
}

// CreateMany builds multiple characters and inserts them into the database
// Relations objects are also inserted and placed in the .R field
func (o CharacterTemplate) CreateMany(ctx context.Context, exec bob.Executor, number int) (models.CharacterSlice, error) {
	var err error
	m := make(models.CharacterSlice, number)

	for i := range m {
		m[i], err = o.Create(ctx, exec)
		if err != nil {
			return nil, err
		}
	}

	return m, nil
}

// MustCreateMany builds multiple characters and inserts them into the database
// Relations objects are also inserted and placed in the .R field
// panics if an error occurs
func (o CharacterTemplate) MustCreateMany(ctx context.Context, exec bob.Executor, number int) models.CharacterSlice {
	m, err := o.CreateMany(ctx, exec, number)
	if err != nil {
		panic(err)
	}
	return m
}

// CreateManyOrFail builds multiple characters and inserts them into the database
// Relations objects are also inserted and placed in the .R field
// It calls `tb.Fatal(err)` on the test/benchmark if an error occurs
func (o CharacterTemplate) CreateManyOrFail(ctx context.Context, tb testing.TB, exec bob.Executor, number int) models.CharacterSlice {
	tb.Helper()
	m, err := o.CreateMany(ctx, exec, number)
	if err != nil {
		tb.Fatal(err)
		return nil
	}
	return m
}

